/* ============================================================
   gsocd-shared / loading-splash
   Pantalla de carga unificada.

   Diseno final (21/09/2026): el video real de marca (recortado a
   6s, loop limpio) va arriba, quieto en su lugar. Abajo, una barra
   de progreso real -- rellena hacia el 85% mientras espera (ease-
   out, nunca llega sola al 100%) y SOLO salta a completo cuando
   hide() se llama de verdad -- nunca finge haber terminado antes
   de tiempo. El texto usa el mismo tratamiento de etiqueta pequena
   que ya usan en .field label / .hero-tag: mayusculas, tracking,
   gris.

   Uso:
     GSLoadingSplash.show();
     GSLoadingSplash.show({ text: 'Saving order...' });
     GSLoadingSplash.hide();

   PRODUCCION: el video aqui va embebido en base64 solo para la
   demo -- en los 3 repos de verdad debe subirse como asset estatico
   (mismo patron que ya usan para imagenes) y referenciarse por URL,
   no pegado dentro de este JS compartido. */
(function () {
  'use strict';
  if (window.GSLoadingSplash) return;

  var VIDEO_SRC = 'data:video/mp4;base64,';

  var el = null;
  var fillTimer = null;

  function build() {
    if (el) return el;
    el = document.createElement('div');
    el.id = 'gs-loading-splash';
    el.setAttribute('aria-live', 'polite');
    el.style.cssText = 'position:fixed;inset:0;z-index:99999;display:none;' +
      'flex-direction:column;align-items:center;justify-content:center;gap:18px;' +
      'background:#F7F6F3';
    if (!document.getElementById('gs-loading-splash-css')) {
      var style = document.createElement('style');
      style.id = 'gs-loading-splash-css';
      style.textContent =
        '.gs-splash-track{width:150px;height:2px;background:#E0D9CC;border-radius:2px;overflow:hidden}' +
        '.gs-splash-fill{width:0;height:100%;background:linear-gradient(90deg,#8C6F2A,#E8CE85);' +
        'transition:width .35s ease-out}' +
        '.gs-splash-fill.done{transition:width .18s ease-out}';
      document.head.appendChild(style);
    }
    el.innerHTML =
      '<video autoplay muted loop playsinline style="width:220px;height:auto;mix-blend-mode:multiply">' +
      '<source src="' + VIDEO_SRC + '" type="video/mp4"></video>' +
      '<div class="gs-splash-track"><div class="gs-splash-fill" id="gs-splash-fill"></div></div>' +
      '<div id="gs-loading-splash-text" style="font-family:Inter,sans-serif;font-size:10px;' +
      'letter-spacing:.14em;text-transform:uppercase;color:#6B6B6B;font-weight:600;' +
      'text-align:center;padding:0 20px;min-height:12px"></div>';
    document.body.appendChild(el);
    return el;
  }

  window.GSLoadingSplash = {
    show: function (opts) {
      var node = build();
      node.querySelector('#gs-loading-splash-text').textContent = (opts && opts.text) || '';
      var fill = node.querySelector('#gs-splash-fill');
      fill.classList.remove('done');
      fill.style.width = '0%';
      node.style.display = 'flex';
      void fill.getBoundingClientRect();
      // Se acerca al 85% con pasos que se hacen mas lentos -- nunca
      // llega sola al 100%, eso solo pasa cuando de verdad termino.
      var steps = [
        [60, '45%'], [220, '62%'], [500, '72%'], [1000, '79%'], [1900, '84%'], [3200, '85%']
      ];
      steps.forEach(function (s) {
        setTimeout(function () { if (node.style.display !== 'none') fill.style.width = s[1]; }, s[0]);
      });
    },
    hide: function () {
      if (el) {
        var fill = el.querySelector('#gs-splash-fill');
        if (fill) { fill.classList.add('done'); fill.style.width = '100%'; }
        setTimeout(function () { if (el) el.style.display = 'none'; }, 160);
      }
    }
  };
})();
